import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g1-3/bot.mjs';

const chi = (tz = 'America/Chicago') => ({ id: 'u_1', phone: '+13125550142', timezone: tz });
const at = (iso) => new Date(iso);

// Fixed cases
let r = checkSms(chi(), at('2026-10-23T15:00:00Z')); // 10:00 CDT
assert.equal(r.allowed, true); assert.equal(r.nextAllowedAt, null);

r = checkSms(chi(), at('2026-10-23T03:00:00Z')); // 22:00 CDT on 10-22
assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');

r = checkSms(chi(), at('2026-10-23T12:59:59.999Z')); // 07:59:59.999 CDT
assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');

r = checkSms(chi(), at('2026-10-23T13:00:00.000Z')); // 08:00:00 CDT exact
assert.equal(r.allowed, true);

r = checkSms(chi(), at('2026-10-24T01:59:59.999Z')); // 20:59:59.999 CDT
assert.equal(r.allowed, true);

r = checkSms(chi(), at('2026-10-24T02:00:00.000Z')); // 21:00 CDT exact
assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), '2026-10-25T13:00:00.000Z');

// DST: fall back Sun 2026-11-01 in Chicago (CDT->CST), spring forward Sun 2026-03-08
r = checkSms(chi(), at('2026-11-02T03:00:00Z')); // Sun Nov 1 22:00 CST?? check: Nov1 2am CDT->1am CST; 03:00Z = 21:00 CST Nov 1
assert.equal(r.allowed, false);
assert.equal(r.nextAllowedAt.toISOString(), '2026-11-02T14:00:00.000Z'); // Mon Nov 2 08:00 CST
r = checkSms(chi(), at('2026-03-08T03:00:00Z')); // Sat Mar 7 21:00 CST
assert.equal(r.nextAllowedAt.toISOString(), '2026-03-08T13:00:00.000Z'); // Sun Mar 8 08:00 CDT

// Half-hour zone: Asia/Kolkata = UTC+05:30
r = checkSms(chi('Asia/Kolkata'), at('2026-10-23T02:00:00Z')); // 07:30 IST
assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T02:30:00.000Z');
r = checkSms(chi('Asia/Kolkata'), at('2026-10-23T02:30:00Z')); // 08:00 IST
assert.equal(r.allowed, true);

// Half-hour + DST: Australia/Adelaide (UTC+9:30 in winter, +10:30 in summer)
r = checkSms(chi('Australia/Adelaide'), at('2026-10-22T12:00:00Z')); // Oct 22 22:30 ACDT? (DST started Oct 4 2026)
assert.equal(r.allowed, false);
assert.equal(r.nextAllowedAt.toISOString(), '2026-10-22T21:30:00.000Z'); // Oct 23 08:00 ACDT(+10:30)

// Unknown / missing / odd zones -> blocked, no retry time
for (const tz of [null, undefined, '', 'Mars/Olympus', '+05:00', 'america/chicago ', 42]) {
  r = checkSms(chi(tz), at('2026-10-23T15:00:00Z'));
  if (tz === 'america/chicago ') continue; // informational; see below
  assert.equal(r.allowed, false, String(tz)); assert.equal(r.nextAllowedAt, null, String(tz));
}

// Bad phone -> blocked, null
r = checkSms({ id: 'x', phone: '3125550142', timezone: 'America/Chicago' }, at('2026-10-23T15:00:00Z'));
assert.equal(r.allowed, false); assert.equal(r.nextAllowedAt, null);
r = checkSms({ id: 'x', timezone: 'America/Chicago' }, at('2026-10-23T15:00:00Z'));
assert.equal(r.allowed, false);

// Invalid now throws
assert.throws(() => checkSms(chi(), new Date('nope')), TypeError);
assert.throws(() => checkSms(chi(), 1234), TypeError);

// Property: for many zones and instants across 2026, every blocked result with a
// non-null nextAllowedAt is exact: allowed at it, blocked 1 ms before, and later than now.
const zones = ['America/Chicago','America/New_York','America/Los_Angeles','America/Anchorage','Pacific/Honolulu',
  'Asia/Kolkata','Asia/Kathmandu','Australia/Adelaide','Australia/Lord_Howe','America/St_Johns','Europe/London','Asia/Tokyo','UTC','America/Santiago'];
let n = 0, blockedCount = 0;
const start = Date.UTC(2026, 0, 1);
for (const tz of zones) {
  for (let t = start; t < start + 365 * 864e5; t += 47 * 60e3) { // every 47 min, irregular vs hours
    const now = new Date(t);
    const res = checkSms(chi(tz), now);
    n++;
    if (res.allowed) continue;
    blockedCount++;
    assert.ok(res.nextAllowedAt instanceof Date, tz);
    const nx = res.nextAllowedAt.getTime();
    assert.ok(nx > t, `${tz} next not in future at ${now.toISOString()}`);
    assert.equal(checkSms(chi(tz), new Date(nx)).allowed, true, `${tz} not allowed at next ${res.nextAllowedAt.toISOString()}`);
    assert.equal(checkSms(chi(tz), new Date(nx - 1)).allowed, false, `${tz} allowed 1ms before next ${res.nextAllowedAt.toISOString()}`);
  }
}
console.log(`property ok: ${n} checks, ${blockedCount} blocked, ${zones.length} zones`);
console.log('all fixed cases ok');
EOF
